<div class="commerce-summary">
<?php foreach($summary['items'] as $line): ?><div class="commerce-line"><div class="grow"><strong><?= e($line['title']) ?></strong><?php if((int)$line['variant_id']): ?><span class="hint"> / SKU #<?= (int)$line['variant_id'] ?></span><?php endif ?></div><strong><?= e($summary['currency'].' '.money((int)$line['amount'])) ?></strong></div><?php endforeach ?>
<?php foreach($summary['promotions'] as $promo): ?><div class="commerce-metric"><span><?= e($promo['name']) ?></span><span>&minus; <?= e($summary['currency'].' '.money((int)$promo['saving'])) ?></span></div><?php endforeach ?>
<div class="commerce-metric"><span><?= t('Shipping') ?></span><strong><?= e($summary['currency'].' '.money((int)$summary['shipping'])) ?></strong></div><div class="commerce-total"><span><?= t('Total to pay') ?></span><strong><?= e($summary['currency'].' '.money((int)$summary['total'])) ?></strong></div><p class="hint"><?= t('Line amounts already include discounts. Each unit keeps its allocated shipping and discount for refunds.') ?></p></div>